const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Upper Arrow Lake area
  const upperArrowLake = ee.Geometry.Rectangle([-117.5, 49.4, -117.1, 49.6]);

  // October 22, 2018
  const date = '2018-10-22';
  const startDate = ee.Date(date);
  const endDate = startDate.advance(1, 'day');

  // Sentinel-2 collection for the date
  const s2 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(upperArrowLake)
    .filterDate(startDate, endDate)
    .select(['B2', 'B3', 'B4', 'B8', 'B11', 'QA60'])
    .filterMetadata('CLOUDY_PIXEL_PERCENTAGE', 'less_than', 95);

  const imageCount = s2.size().getInfo();
  print(`Total Sentinel-2 images on Oct 22, 2018: ${imageCount}`);

  if (imageCount === 0) {
    print("No Sentinel-2 imagery available for October 22, 2018.");
    print("C1");
    return;
  }

  // Extract images and sort by time
  const imageList = s2.toList(s2.size());
  const images = [];
  for (let i = 0; i < imageCount; i++) {
    const img = ee.Image(imageList.get(i));
    const timestamp = img.getNumber('system:time_start').getInfo();
    images.push({ img: img, time: new Date(timestamp), idx: i });
  }

  // Sort by acquisition time
  images.sort((a, b) => a.time - b.time);

  print(`Image times (UTC):`);
  images.forEach((d, i) => {
    print(`  ${i}: ${d.time.toUTCString()}`);
  });

  if (imageCount < 2) {
    print("Only 1 image found; cannot compare morning vs afternoon.");
    print("C1");
    return;
  }

  // Use first image as morning, last as afternoon
  const morningImg = images[0].img;
  const afternoonImg = images[imageCount - 1].img;

  // Function to calculate fog coverage using cloud probability
  // Fog = high NIR reflectance + low NDVI + high cloud probability
  function calculateFogCoverage(image) {
    const B2 = image.select('B2');
    const B3 = image.select('B3');
    const B4 = image.select('B4');
    const B8 = image.select('B8');
    const B11 = image.select('B11');
    const QA60 = image.select('QA60');

    // Cloud probability (bit 10 and 11 of QA60 indicate clouds)
    const cloudMask = QA60.bitwiseAnd(1024).eq(0).and(QA60.bitwiseAnd(2048).eq(0));

    // NDVI for fog detection (fog has low NDVI)
    const NDVI = B8.subtract(B4).divide(B8.add(B4));

    // Cloud reflectance: blue and red bands high
    const cloudReflect = B3.add(B4).divide(2);

    // Fog indicator: high reflectance + low NDVI + cloudy
    const fogIndicator = cloudReflect.multiply(cloudMask.float()).where(NDVI.gt(0.3), 0);

    // Count pixels with fog signal
    const fogCount = fogIndicator.reduceRegion(
      { reducer: ee.Reducer.count(), 
        geometry: upperArrowLake, 
        scale: 20, 
        maxPixels: 1e9 }
    ).get('B2');

    const totalCount = cloudMask.reduceRegion(
      { reducer: ee.Reducer.count(), 
        geometry: upperArrowLake, 
        scale: 20, 
        maxPixels: 1e9 }
    ).get('B2');

    return { fogCount: fogCount, totalCount: totalCount };
  }

  const morningFog = calculateFogCoverage(morningImg);
  const afternoonFog = calculateFogCoverage(afternoonImg);

  const morningFogCount = morningFog.fogCount.getInfo();
  const afternoonFogCount = afternoonFog.fogCount.getInfo();
  const totalPixels = morningFog.totalCount.getInfo();

  print(`Morning fog pixels: ${morningFogCount} / ${totalPixels}`);
  print(`Afternoon fog pixels: ${afternoonFogCount} / ${totalPixels}`);

  if (totalPixels === 0 || morningFogCount === null || afternoonFogCount === null) {
    print("No valid pixels for comparison.");
    print("C2");
    return;
  }

  const morningCoverage = (morningFogCount / totalPixels) * 100;
  const afternoonCoverage = (afternoonFogCount / totalPixels) * 100;

  print(`Morning fog coverage: ${morningCoverage.toFixed(2)}%`);
  print(`Afternoon fog coverage: ${afternoonCoverage.toFixed(2)}%`);
  print(`Decrease: ${(morningCoverage - afternoonCoverage).toFixed(2)}%`);

  if (isNaN(morningCoverage) || isNaN(afternoonCoverage)) {
    print("C3");
    return;
  }

  if (morningCoverage > afternoonCoverage) {
    print("A");
  } else {
    print("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
